import os
import hmac
import hashlib
import json
import re
import yaml
import tempfile
import threading
from flask import Flask, request, jsonify, abort
from functools import wraps
from datetime import datetime, timedelta

app = Flask(__name__)

SERVICE_SECRET = os.environ.get('SERVICE_SECRET', '')
DATA_DIR = os.environ.get('DATA_DIR', '/var/lib/app/data')

# Rate limiting state
rate_limit_lock = threading.Lock()
request_counts = {}

def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not SERVICE_SECRET:
            abort(503, description='Service not configured')
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)
        token = auth_header[7:]
        # HMAC-based token: timestamp.signature
        parts = token.split('.')
        if len(parts) != 2:
            abort(401)
        timestamp_str, signature = parts
        try:
            ts = int(timestamp_str)
            if abs(datetime.utcnow().timestamp() - ts) > 300:
                abort(401, description='Token expired')
        except (ValueError, OSError):
            abort(401)
        expected_sig = hmac.new(
            SERVICE_SECRET.encode('utf-8'),
            timestamp_str.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()
        if not constant_time_compare(signature, expected_sig):
            abort(401)
        return f(*args, **kwargs)
    return decorated

def rate_limit(max_requests=100, window=60):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            client_ip = request.remote_addr
            now = datetime.utcnow()
            with rate_limit_lock:
                if client_ip not in request_counts:
                    request_counts[client_ip] = []
                request_counts[client_ip] = [
                    t for t in request_counts[client_ip]
                    if now - t < timedelta(seconds=window)
                ]
                if len(request_counts[client_ip]) >= max_requests:
                    abort(429)
                request_counts[client_ip].append(now)
            return f(*args, **kwargs)
        return decorated
    return decorator


class ConfigurationManager:
    """Manages service configuration with hot-reload support."""

    def __init__(self):
        self._config_cache = {}
        self._lock = threading.RLock()
        self._watchers = []

    def register_watcher(self, callback):
        self._watchers.append(callback)

    def get_config(self, namespace):
        with self._lock:
            if namespace in self._config_cache:
                return self._config_cache[namespace]
        return None

    def _parse_config_document(self, raw_content, format_hint='auto'):
        """Parse configuration from raw string content.

        Supports JSON and YAML formats. Format is auto-detected
        based on content structure if format_hint is 'auto'.
        """
        if not raw_content or not raw_content.strip():
            return {}

        content = raw_content.strip()

        # Auto-detect format
        if format_hint == 'auto':
            if content.startswith('{'):
                format_hint = 'json'
            else:
                format_hint = 'yaml'

        if format_hint == 'json':
            return json.loads(content)
        elif format_hint == 'yaml':
            # Use the full-featured YAML loader for complex configs
            # that may include custom tags and type coercion
            return yaml.load(content, Loader=yaml.FullLoader)
        else:
            raise ValueError(f'Unsupported format: {format_hint}')

    def update_config(self, namespace, raw_content, format_hint='auto'):
        """Update configuration for a namespace from raw content."""
        if not re.match(r'^[a-z][a-z0-9_-]{0,62}$', namespace):
            raise ValueError('Invalid namespace')

        parsed = self._parse_config_document(raw_content, format_hint)

        if not isinstance(parsed, dict):
            raise ValueError('Configuration must be a mapping')

        # Validate no excessively deep nesting
        def check_depth(obj, depth=0):
            if depth > 10:
                raise ValueError('Configuration too deeply nested')
            if isinstance(obj, dict):
                for v in obj.values():
                    check_depth(v, depth + 1)
            elif isinstance(obj, list):
                for v in obj:
                    check_depth(v, depth + 1)

        check_depth(parsed)

        with self._lock:
            self._config_cache[namespace] = parsed

        # Notify watchers
        for watcher in self._watchers:
            try:
                watcher(namespace, parsed)
            except Exception:
                pass

        return parsed


class PipelineRegistry:
    """Registry for data processing pipelines."""

    ALLOWED_STAGES = {
        'normalize', 'validate', 'transform', 'aggregate',
        'filter', 'enrich', 'deduplicate', 'compress'
    }

    def __init__(self, config_manager):
        self._pipelines = {}
        self._config_manager = config_manager
        config_manager.register_watcher(self._on_config_change)

    def _on_config_change(self, namespace, config):
        """React to configuration changes."""
        if 'pipelines' in config:
            for name, stages in config['pipelines'].items():
                if isinstance(stages, list):
                    valid_stages = [s for s in stages if s in self.ALLOWED_STAGES]
                    self._pipelines[f"{namespace}/{name}"] = valid_stages

    def get_pipeline(self, pipeline_id):
        return self._pipelines.get(pipeline_id, [])

    def list_pipelines(self):
        return list(self._pipelines.keys())


config_manager = ConfigurationManager()
pipeline_registry = PipelineRegistry(config_manager)


@app.route('/api/v2/config/<namespace>', methods=['PUT'])
@require_auth
@rate_limit(max_requests=20, window=60)
def update_configuration(namespace):
    """Update configuration for a namespace.

    Accepts raw configuration content in the request body.
    Content-Type header determines parsing format.
    """
    content_type = request.content_type or ''
    raw_body = request.get_data(as_text=True)

    if not raw_body:
        abort(400, description='Empty request body')

    if len(raw_body) > 65536:
        abort(413, description='Configuration too large')

    # Determine format from content type
    if 'json' in content_type:
        format_hint = 'json'
    elif 'yaml' in content_type or 'x-yaml' in content_type:
        format_hint = 'yaml'
    else:
        format_hint = 'auto'

    try:
        result = config_manager.update_config(namespace, raw_body, format_hint)
        return jsonify({
            'status': 'updated',
            'namespace': namespace,
            'keys': list(result.keys()) if isinstance(result, dict) else []
        })
    except (ValueError, json.JSONDecodeError, yaml.YAMLError) as e:
        abort(400, description=str(e))


@app.route('/api/v2/config/<namespace>', methods=['GET'])
@require_auth
@rate_limit(max_requests=100, window=60)
def get_configuration(namespace):
    """Retrieve current configuration for a namespace."""
    if not re.match(r'^[a-z][a-z0-9_-]{0,62}$', namespace):
        abort(400, description='Invalid namespace')

    config = config_manager.get_config(namespace)
    if config is None:
        abort(404)

    return jsonify({'namespace': namespace, 'config': config})


@app.route('/api/v2/pipelines', methods=['GET'])
@require_auth
@rate_limit(max_requests=100, window=60)
def list_pipelines():
    """List all registered pipelines."""
    return jsonify({'pipelines': pipeline_registry.list_pipelines()})


@app.route('/api/v2/pipelines/<path:pipeline_id>/execute', methods=['POST'])
@require_auth
@rate_limit(max_requests=50, window=60)
def execute_pipeline(pipeline_id):
    """Execute a registered pipeline on input data."""
    stages = pipeline_registry.get_pipeline(pipeline_id)
    if not stages:
        abort(404, description='Pipeline not found')

    payload = request.get_json(silent=True)
    if not payload or 'data' not in payload:
        abort(400, description='Missing data field')

    # Simulate pipeline execution
    result = {
        'pipeline_id': pipeline_id,
        'stages_executed': stages,
        'input_size': len(str(payload['data'])),
        'status': 'completed'
    }

    return jsonify(result)


@app.route('/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'healthy', 'timestamp': datetime.utcnow().isoformat()})


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
